/** Actual JS CPU procedural effect timeline. No fluid fixture or synthetic illustration.
 * The report and fixed-camera PNG use the exact atlas generated by the public Effect API.
 */
import {createEffect} from '../bindings/web/effects.mjs';
import {renderAtlasViews} from './atlas_preview.mjs';
import {writeFile,mkdir} from 'node:fs/promises';
import {createHash} from 'node:crypto';
import {join} from 'node:path';
const out=process.argv[2];if(!out)throw new Error('Usage: node lab/profile_procedural.mjs output-directory');
await mkdir(out,{recursive:true});
const times=[0,4,8],width=320,height=200,rows=[];
for(const key of ['cumulus_cloud','ground_fog','dust']){
 const e=await createEffect(key,{quality:'medium'});try{
  e.play();let previous=0;const sheet=new Uint8Array(width*times.length*height*4),frames=[];
  for(let i=0;i<times.length;i++){
   const time=times[i];e.advance(time-previous);previous=time;
   const start=performance.now(),atlas=await e.atlasRGBA8(),generationMs=performance.now()-start;
   const result=renderAtlasViews({atlas,cells:[...e.renderCells],extent:e.extent,densityCap:e.config.densityCap,material:e.definition.material,background:key==='cumulus_cloud'?'sky':'dark',width,height,steps:64});
   // Only the fixed-domain panel; all three frames share identical camera coordinates.
   for(let y=0;y<height;y++)sheet.set(result.rgba.subarray(y*width*8,y*width*8+width*4),(y*width*times.length+i*width)*4);
   frames.push({time,generationMs,cachedInitialSnapshot:time===0,stats:result.stats,view:result.views[0],atlasSha256:result.atlasSha256});
  }
  if(new Set(frames.map(f=>f.atlasSha256)).size!==times.length)throw new Error('procedural timeline did not change: '+key);
  const file=key+'.rgba';await writeFile(join(out,file),sheet);rows.push({key,quality:'medium',cells:[...e.renderCells],extent:e.extent,width:width*times.length,height,file,frames,rawImageSha256:createHash('sha256').update(sheet).digest('hex')});
 }finally{e.dispose();}
}
await writeFile(join(out,'timeline.json'),JSON.stringify({schema:'vapor.procedural-timeline/1',evidence:'actual JS CPU Effect API and software raymarch fixed-domain frames, not Rust fluid or game engine',times,rows},null,2)+'\n');
